export function pageSegments(sort: SortSpec, cursor: PageCursor | null, firstParameter: number): PageSegment[] {
	const ascending = sort.direction === "ASC";
	const comparison = ascending ? ">" : "<";
	const orderBy = `${sort.expr} ${sort.direction} ${ascending ? "NULLS FIRST" : "NULLS LAST"}, core.id ${sort.direction}`;
	const segment = (isNull: boolean, after: PageCursor | null): PageSegment => {
		const values: unknown[] = [];
		const bind: Bind = value => {
			values.push(value);
			return `$${firstParameter + values.length - 1}`;
		};
		if (isNull) {
			return { where: `(${sort.expr}) IS NULL${after ? ` AND core.id ${comparison} ${bind(after.id)}::text` : ""}`, orderBy, values };
		}
		const keyset = after ? ` AND ((${sort.expr}), core.id) ${comparison} (${bind(after.value)}::${sort.type}, ${bind(after.id)}::text)` : "";
		return { where: `(${sort.expr}) IS NOT NULL${keyset}`, orderBy, values };
	};

